import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"RM选择","description":"选择合适的重量","frontmatter":{"title":"RM选择","description":"选择合适的重量","date":"2026-05-29T00:00:00.000Z","category":"健康健身","tags":["力量训练"],"order":2},"headers":[],"relativePath":"articles/fitness/strength/RM.md","filePath":"articles/fitness/strength/RM.md","articleMeta":{"updated":"2026-05-29","words":1075,"minutes":3}}`),a={name:`articles/fitness/strength/RM.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="_1-什么是rm" tabindex="-1">1. 什么是RM <a class="header-anchor" href="#_1-什么是rm" aria-label="Permalink to “1. 什么是RM”">​</a></h2><p>&quot;RM&quot;是Repetition Maximum的缩写，中文意思是“最大重复次数”。<strong>不同人的力量不同，RM用来表示在特定的负荷下，能够完成的最大次数。</strong>在全力以赴的情况下，假如你在50KG重量下只能做一次深蹲，50KG就是你的1RM；能做5次，那么该重量就是5RM；以此类推。</p><p>不同的 RM 范围对应着不同的训练目标，通过了解自己的RM，可以更科学地制定训练计划，以达到不同的健身目标：<strong>1-5RM</strong> 的大重量训练主要用于增加肌肉力量。比如，进行深蹲时，选择只能重复做 1 到 5 次的重量，可以极大地刺激肌肉力量的增长。<strong>6-12RM</strong> 的中等重量训练有助于增加肌肉体积。这是很多健身爱好者在增肌阶段常采用的范围，例如做哑铃卧推，选择能重复 6 到 12 次的重量，可以有效地促进肌肉的生长。<strong>12RM 以上</strong>的较轻重量训练则更侧重于提高肌肉耐力。像进行多次数的卷腹训练，可以增强腹部肌肉的耐力。而过高的RM则会被视为无效训练。</p><h2 id="_2-如何测量rm" tabindex="-1">2. 如何测量RM <a class="header-anchor" href="#_2-如何测量rm" aria-label="Permalink to “2. 如何测量RM”">​</a></h2><p>直接测量法：在有保护且充分热身的情况下，当你能够完成一次动作且没有余力时，这个重量就是1RM。</p><p>公式估算法：其中一种较为常用的是 Epley 公式，1RM = 重量 × (1 + 重复次数 ÷30)。例如，如果你用 50 公斤的重量完成了 8 次重复的卧推，那么根据这个公式估算的 1RM 重量为：50×(1 + 8÷30) ≈ 63.33 公斤。</p><p>一个在线的RM计算器：<a href="https://gcupfpa.github.io/" target="_blank" rel="noreferrer">https://gcupfpa.github.io</a></p><h2 id="_3-如何使用rm" tabindex="-1">3. 如何使用RM <a class="header-anchor" href="#_3-如何使用rm" aria-label="Permalink to “3. 如何使用RM”">​</a></h2><p><strong>重量选择不小于15rm重量，1-15rm之间的重量都可以，建议6-15rm</strong>，风险低+肌力大的肌群（如胸，背阔）可以选择靠近6rm的重量；风险高+肌力大的肌群（如腿）可以选择靠近10rm左右的重量；肌力小的肌群（如肩）可以选择靠近15rm的重量。</p><p><strong>重量选择好之后，每组做的次数减1或减2</strong>。假设使用6RM训练，则每组做5个；12RM进行训练，则每组做10个。这样保证了训练强度的同时，下一组直至最后一组也能做足5个，训练量够了才能帮助我们更好进步。要避免重量过轻，没有刺激到肌肉达到训练的效果。</p><h2 id="_4-确保动作到位" tabindex="-1">4. 确保动作到位 <a class="header-anchor" href="#_4-确保动作到位" aria-label="Permalink to “4. 确保动作到位”">​</a></h2><p>包括但不限于：（1）向心离心行程做全；（2）全程纯靠肌肉张力控制住重量，无任何其他部位借力、惯性、爆发力等，避免动作过快；（3）肌纤维拉到最长时（比如卧推触胸那一刻，引体向上最下的那一瞬间，深蹲蹲到最下面那一刻，等等）暂停一下（这个暂停的时间可以无限短，比如0.3秒，也可以，但是一定要能主观感受到那个暂停瞬间）。</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};